"use client";

import { useState } from "react";
import { usePathname } from "next/navigation";
import Image from "next/image";
import Link from "next/link";

const links = [
  { label: "Home", href: "/", width: "30%" },
  { label: "About", href: "/about", width: "45%" },
  { label: "Expertise", href: "/expertise", width: "65%" },
  { label: "Teaching", href: "/teaching", width: "75%" },
  // { label: "Publications", href: "/publications", width: "85%" },
  { label: "Gallery", href: "/gallery", width: "85%" },
  { label: "Selected Work", href: "/selected-work", width: "100%" },
];

export default function Header() {
  const [menuOpen, setMenuOpen] = useState(false);
  const pathname = usePathname();
  const isHome = pathname === "/";

  const closeMenu = () => setMenuOpen(false);

  return (
    <div className={isHome ? "home-page" : undefined}>
      <header className="header">
        <div className="brand">
          <Link className="logo" href="/">
            <Image
              src="/images/sanjay-logo.svg"
              alt="Dr. Sanjay Sonar Logo"
              width={232}
              height={52}
              priority
            />
          </Link>
        </div>

        <nav className="nav">
          {links.map((link) => {
            const style = { "--underline-width": link.width };
            const isActive =
              pathname === link.href || (link.href !== "/" && pathname?.startsWith(link.href));

            if (link.href && link.href.startsWith("/")) {
              return (
                <Link
                  key={link.label}
                  href={link.href}
                  className={`navLink ${isActive ? "active" : ""}`}
                  style={style}
                >
                  {link.label}
                </Link>
              );
            }

            return (
              <a key={link.label} href={link.href} className={`navLink ${isActive ? "active" : ""}`} style={style}>
                {link.label}
              </a>
            );
          })}
        </nav>
      

        <Link href="/consultation" className="cta site-cta">
          Consultation
        </Link>

        <button
          className={`menuBtn ${menuOpen ? "active" : ""}`}
          onClick={() => setMenuOpen(!menuOpen)}
          aria-label="Toggle menu"
        >
          <span></span>
          <span></span>
          <span></span>
        </button>
      </header>

      <div className={`mobileMenu ${menuOpen ? "open" : ""}`}>
        <nav className="mobileNav">
          {links.map((link) => {
            const isActive =
              pathname === link.href || (link.href !== "/" && pathname?.startsWith(link.href));

            if (link.href && link.href.startsWith("/")) {
              return (
                <Link key={link.label} href={link.href} className={isActive ? "active" : undefined} onClick={closeMenu}>
                  {link.label}
                </Link>
              );
            }

            return (
              <a key={link.label} href={link.href} onClick={closeMenu}>
                {link.label}
              </a>
            );
          })}

          <Link href="/consultation" className="mobileCta site-cta" onClick={closeMenu}>
            Consultation
          </Link>
        </nav>
      </div>
    </div>
  );
}
